from ortools.linear_solver import pywraplp
import json

def main():
    apartment_width = 10.0
    apartment_height = 10.0
    furniture_types = [1, 2, 3, 4, 5]

    width = {1: 3.0, 2: 4.0, 3: 2.0, 4: 3.0, 5: 2.0}
    height = {1: 3.0, 2: 2.0, 3: 2.0, 4: 2.0, 5: 3.0}
    comfort = {1: 35.0, 2: 40.0, 3: 27.0, 4: 23.0, 5: 43.0}

    solver = pywraplp.Solver.CreateSolver("SCIP")
    INF = solver.infinity()

    solver.SetTimeLimit(30000)
    solver.SetNumThreads(1)

    place = {}
    x = {}
    y = {}
    rotate = {}
    eff_width = {}
    eff_height = {}

    for i in furniture_types:
        place[i] = solver.BoolVar(f"place_{i}")
        x[i] = solver.NumVar(0.0, apartment_width, f"x_{i}")
        y[i] = solver.NumVar(0.0, apartment_height, f"y_{i}")
        rotate[i] = solver.BoolVar(f"rotate_{i}")
        eff_width[i] = solver.NumVar(0.0, apartment_width, f"eff_width_{i}")
        eff_height[i] = solver.NumVar(0.0, apartment_height, f"eff_height_{i}")

    solver.Add(place[1] == 1)

    for i in furniture_types:
        M = max(width[i], height[i]) * 2

        solver.Add(eff_width[i] <= width[i] + (height[i] - width[i]) * rotate[i] + M * (1 - place[i]))
        solver.Add(eff_width[i] >= width[i] + (height[i] - width[i]) * rotate[i] - M * (1 - place[i]))

        solver.Add(eff_width[i] <= M * place[i])
        solver.Add(eff_width[i] >= -M * place[i])

    for i in furniture_types:
        M = max(width[i], height[i]) * 2

        solver.Add(eff_height[i] <= height[i] + (width[i] - height[i]) * rotate[i] + M * (1 - place[i]))
        solver.Add(eff_height[i] >= height[i] + (width[i] - height[i]) * rotate[i] - M * (1 - place[i]))

        solver.Add(eff_height[i] <= M * place[i])
        solver.Add(eff_height[i] >= -M * place[i])

    for i in furniture_types:
        M_x = apartment_width * 2
        solver.Add(x[i] + eff_width[i] <= apartment_width + M_x * (1 - place[i]))

        M_y = apartment_height * 2
        solver.Add(y[i] + eff_height[i] <= apartment_height + M_y * (1 - place[i]))

    for i in furniture_types:
        solver.Add(x[i] <= apartment_width * place[i])
        solver.Add(y[i] <= apartment_height * place[i])
        solver.Add(rotate[i] <= place[i])

    for i in furniture_types:
        for j in furniture_types:
            if i < j:
                d1 = solver.BoolVar(f"d1_{i}_{j}")
                d2 = solver.BoolVar(f"d2_{i}_{j}")
                d3 = solver.BoolVar(f"d3_{i}_{j}")
                d4 = solver.BoolVar(f"d4_{i}_{j}")
                d5 = solver.BoolVar(f"d5_{i}_{j}")

                solver.Add(d1 + d2 + d3 + d4 + d5 >= 1)

                M = apartment_width + apartment_height

                solver.Add(x[i] + eff_width[i] <= x[j] + M * (1 - d1))

                solver.Add(x[j] + eff_width[j] <= x[i] + M * (1 - d2))

                solver.Add(y[i] + eff_height[i] <= y[j] + M * (1 - d3))

                solver.Add(y[j] + eff_height[j] <= y[i] + M * (1 - d4))

                solver.Add(place[i] + place[j] <= 1 + 2 * (1 - d5))

    objective = solver.Objective()
    for i in furniture_types:
        objective.SetCoefficient(place[i], comfort[i])
    objective.SetMaximization()

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL:
        total_comfort_value = int(sum(place[i].solution_value() * comfort[i] for i in furniture_types))
        placements = []
        for i in furniture_types:
            if place[i].solution_value() > 0.5:
                placements.append([
                    i,
                    int(round(x[i].solution_value())),
                    int(round(y[i].solution_value())),
                    int(round(rotate[i].solution_value()))
                ])
        print(json.dumps({
            "total_comfort_value": total_comfort_value,
            "placements": placements
        }))
    else:
        print(json.dumps({
            "total_comfort_value": 0,
            "placements": []
        }))

if __name__ == "__main__":
    main()
